#!/bin/bash
# Differential harness: compares stdout, stderr and exit status of the C++
# binary and the Rust port for each argument vector fed on stdin.
# Core dumps are disabled — both binaries abort on purpose for bad input, and
# routing those through apport dominates the runtime otherwise.
ulimit -c 0
CPP=/workspace/dataset/test13_executable
RS=${RS:-/output/test13}
one() {
  local line="$1"
  eval "set -- $line"
  local co cr ro rr ce re
  ce=$("$CPP" "$@" 2>&1 >/dev/null); co=$("$CPP" "$@" 2>/dev/null); cr=$?
  re=$("$RS"  "$@" 2>&1 >/dev/null); ro=$("$RS"  "$@" 2>/dev/null); rr=$?
  if [ "$co" = "$ro" ] && [ "$cr" = "$rr" ] && [ "$ce" = "$re" ]; then
    echo "P"
  else
    printf 'MISMATCH args=[%s]\n  cpp: rc=%s out=[%s] err=[%s]\n  rs : rc=%s out=[%s] err=[%s]\n' \
      "$line" "$cr" "$co" "$ce" "$rr" "$ro" "$re"
  fi
}
export -f one; export CPP RS
xargs -d '\n' -P 32 -I{} bash -c 'one "$@"' _ {} | awk '
  /^P$/ { p++; next }
  { print; f++ }
  END { printf "pass=%d mismatch_lines=%d\n", p, f }'
