   217	    if mag > 60 {
   218	        return (f32::INFINITY, true); // far past FLT_MAX
   219	    }
   220	    if mag < -100 {
   221	        return (0.0, true); // far below the smallest subnormal
   222	    }
   223	    let text = format!("{}e{}", std::str::from_utf8(digits).unwrap(), k);
   224	    let value: f32 = text.parse().unwrap();
   225	    if value.is_infinite() {
   226	        return (value, true);
   227	    }
   228	    // Only a result at or below FLT_MIN can be an underflow, and deciding it
   229	    // needs the exact value rather than the rounded one.
   230	    let erange = value.abs() <= f32::MIN_POSITIVE && decimal_underflow(digits, k, mag);
