    95	/// Increment the digit string, carrying; an all-nines string becomes 1 followed
    96	/// by zeros and bumps the exponent.
    97	fn round_up(sig: &mut Vec<u8>, x: &mut i64) {
    98	    for i in (0..sig.len()).rev() {
    99	        if sig[i] == b'9' {
   100	            sig[i] = b'0';
   101	        } else {
   102	            sig[i] += 1;
   103	            return;
   104	        }
   105	    }
   106	    sig.insert(0, b'1');
   107	    sig.truncate(P);
   108	    *x += 1;
   109	}
   110	
   111	fn trim_zeros(d: &[u8]) -> String {
   112	    let mut end = d.len();
   113	    while end > 0 && d[end - 1] == b'0' {
   114	        end -= 1;
   115	    }
   116	    String::from_utf8_lossy(&d[..end]).into_owned()
   117	}
