//! Conversions between colour spaces.

use super::hsl::Hsl;

pub struct ColorConverter;

impl ColorConverter {
    /// Angular distance between two hues, in degrees.
    ///
    /// The wrap is a single fold rather than a full normalisation, so hues
    /// outside `[0, 360)` are not brought back into range first: a gap wider
    /// than 360 folds straight past zero and comes out negative. Saturation
    /// and lightness play no part.
    pub fn hue_difference(a: &Hsl, b: &Hsl) -> f64 {
        let d = (a.h - b.h).abs();
        if d > 180.0 {
            360.0 - d
        } else {
            d
        }
    }
}
//! Hue / saturation / lightness.
//!
//! The components are stored exactly as given: the constructor neither wraps
//! the hue into `[0, 360)` nor clamps saturation and lightness, which is why a
//! hue of 720 stays 720 and shows up in the conversions below.

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Hsl {
    pub h: f64,
    pub s: f64,
    pub l: f64,
}

impl Hsl {
    pub fn new(h: f64, s: f64, l: f64) -> Self {
